// Package jsconsumer is the durable JetStream pull-consumer scaffold shared by
// Entire's decode-and-dispatch consumers. Each of those used to hand-roll the
// same lifecycle: jetstream.New → CreateOrUpdateConsumer (durable, explicit
// ack, bounded ack-wait, bounded MaxDeliver, filter subject) → Consume → stop
// on context cancel; and the same per-message prologue: open a consumer span
// (re-parented across the NATS hop), decode the payload, and Term on a decode
// error.
//
// This package owns exactly that scaffold and nothing else. Each consumer
// keeps its OWN event type, business dispatch, metrics, and log lines — Start
// takes the consumer's message callback, and Process invokes the consumer's
// handle with the decoded event and the live span. The handler owns the
// message's terminal disposition (Ack/Nak/Term); Process never touches a
// message that decoded.
//
// Lifted from entire-api's internal/jsconsumer (COR-929), folding in the
// module's shutdown classification ([nuts.IsShutdownFetchErr] gates the
// consume-error log so a drain during rollout isn't reported as a fault,
// COR-923) and an optional [natsmsg.KeepInProgress] heartbeat for consumers
// whose handlers legitimately outrun AckWait.
package jsconsumer

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entireio/go-nuts"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	// DefaultAckWait is how long JetStream waits for an ack before redelivery
	// when Config.AckWait is zero — comfortably longer than an RPC round-trip
	// plus a DB upsert, short enough that a stuck message redelivers promptly.
	DefaultAckWait = 30 * time.Second
	// DefaultMaxDeliver caps redelivery before JetStream stops redelivering a
	// message when Config.MaxDeliver is zero.
	DefaultMaxDeliver = 8
)

// Config describes the durable consumer to create and how to trace/log it. The
// filter is given as either FilterSubject (single) or FilterSubjects (multi),
// mirroring jetstream.ConsumerConfig, so a migrated consumer preserves its
// existing on-server filter form exactly.
type Config struct {
	Stream         string        // JetStream stream to bind (must already exist)
	Durable        string        // durable consumer name, stable across restarts
	FilterSubject  string        // set this OR FilterSubjects
	FilterSubjects []string      // set this OR FilterSubject
	AckWait        time.Duration // 0 → DefaultAckWait (see EffectiveAckWait)
	MaxDeliver     int           // 0 → DefaultMaxDeliver (see EffectiveMaxDeliver)
	SpanName       string        // per-message consumer span name (e.g. "repolifecycle.consume")
	Name           string        // short consumer name, used as the log prefix

	// InactiveThreshold mirrors jetstream.ConsumerConfig.InactiveThreshold:
	// how long the durable may go without an active subscription before the
	// server deletes it; zero means never (the JetStream default for
	// durables). Consumers on interest-retention streams set this so a
	// decommissioned durable stops pinning every message it would have
	// received, instead of holding them until the stream's MaxAge.
	InactiveThreshold time.Duration

	// MaxAckPending mirrors jetstream.ConsumerConfig.MaxAckPending: the
	// server-side cap on deliveries outstanding un-acked across ALL replicas
	// sharing the durable; zero uses the server default (1000). Distinct
	// from MaxMessages below, which caps only this process's client-side
	// buffer.
	MaxAckPending int

	// Tracer opens the per-message consumer span; nil uses the global OTel
	// tracer provider.
	Tracer trace.Tracer
	// Logger receives the scaffold's own log lines (decode-term warnings,
	// consume errors); nil uses slog.Default.
	Logger *slog.Logger

	// KeepInProgress runs a natsmsg.KeepInProgress heartbeat while handle
	// executes, for handlers that legitimately outrun AckWait. The extension
	// is capped, so a wedged handler still redelivers — see
	// natsmsg.KeepInProgress. The heartbeat stops when handle returns; a tick
	// racing the handler's own terminal Ack/Nak/Term is a client-side no-op
	// (nats.go marks the message disposed locally) that halts the heartbeat.
	//
	// Setting this forces the prefetch to one message (see MaxMessages): the
	// heartbeat extends only the delivery the handler holds, so anything
	// buffered behind a long handler would exhaust its AckWait unextended.
	KeepInProgress bool

	// MaxMessages caps how many deliveries the consume loop buffers
	// client-side (jetstream.PullMaxMessages); 0 uses the nats.go default
	// (500). AckWait runs from server delivery into that buffer, not from
	// callback dispatch, and callbacks run serially — so a consumer whose
	// handler can approach AckWait should keep this small or queued
	// deliveries expire and redeliver concurrently to other replicas.
	// KeepInProgress forces it to 1; setting both to conflicting values is a
	// Start error.
	MaxMessages int
}

// EffectiveAckWait is the AckWait actually applied to the JetStream consumer:
// Config.AckWait, or DefaultAckWait when zero. Use it — not the raw field —
// anywhere the real value matters, e.g. wiring a natsmsg.KeepInProgress
// heartbeat by hand (a zero ackWait there is a no-op).
func (c Config) EffectiveAckWait() time.Duration {
	if c.AckWait == 0 {
		return DefaultAckWait
	}
	return c.AckWait
}

// EffectiveMaxDeliver is the MaxDeliver actually applied to the JetStream
// consumer: Config.MaxDeliver, or DefaultMaxDeliver when zero. Use it — not
// the raw field — when building a backoff.Policy for this consumer's
// messages: the two packages read zero differently (here it means "default
// to DefaultMaxDeliver"; on the policy it means unlimited redeliveries, the
// jetstream.ConsumerConfig semantics), so passing a zero Config.MaxDeliver
// through verbatim would make TermOnExhaustion never fire on the broker's
// real final delivery and orphan work-queue messages (COR-762).
func (c Config) EffectiveMaxDeliver() int {
	if c.MaxDeliver == 0 {
		return DefaultMaxDeliver
	}
	return c.MaxDeliver
}

// validate rejects the configuration errors no retry can fix; shared by
// [Start] (one-shot) and [Run] (supervised, which must fail fast on these
// rather than retry them forever).
func (c Config) validate(nc *nats.Conn, onMsg func(jetstream.Msg)) error {
	if c.KeepInProgress && c.MaxMessages > 1 {
		return fmt.Errorf("jsconsumer(%s): KeepInProgress requires MaxMessages <= 1: the heartbeat extends only the in-flight delivery, so %d buffered messages would exhaust AckWait behind a long handler", c.Name, c.MaxMessages)
	}
	if c.Stream == "" {
		return fmt.Errorf("jsconsumer(%s): Stream is required", c.Name)
	}
	if c.Durable == "" {
		// CreateOrUpdateConsumer accepts an empty durable and silently makes
		// an ephemeral, server-named consumer — losing the stable
		// resume-across-restarts behavior this scaffold promises.
		return fmt.Errorf("jsconsumer(%s): Durable is required", c.Name)
	}
	if onMsg == nil {
		return fmt.Errorf("jsconsumer(%s): onMsg is required", c.Name)
	}
	if c.FilterSubject != "" && len(c.FilterSubjects) != 0 {
		return fmt.Errorf("jsconsumer(%s): set FilterSubject or FilterSubjects, not both", c.Name)
	}
	for i, subject := range c.FilterSubjects {
		if subject == "" {
			return fmt.Errorf("jsconsumer(%s): FilterSubjects[%d] is empty", c.Name, i)
		}
	}
	if c.AckWait < 0 {
		return fmt.Errorf("jsconsumer(%s): AckWait must not be negative", c.Name)
	}
	if c.MaxDeliver < -1 {
		return fmt.Errorf("jsconsumer(%s): MaxDeliver must be -1 (unlimited), 0 (default), or positive", c.Name)
	}
	if c.MaxMessages < 0 {
		return fmt.Errorf("jsconsumer(%s): MaxMessages must not be negative", c.Name)
	}
	if c.MaxAckPending < -1 {
		return fmt.Errorf("jsconsumer(%s): MaxAckPending must be -1 (unlimited), 0 (server default), or positive", c.Name)
	}
	if c.InactiveThreshold < 0 {
		return fmt.Errorf("jsconsumer(%s): InactiveThreshold must not be negative", c.Name)
	}
	if nc == nil {
		return fmt.Errorf("jsconsumer(%s): nil nats conn", c.Name)
	}
	return nil
}

func (c Config) tracer() trace.Tracer {
	if c.Tracer == nil {
		return otel.Tracer("github.com/entireio/go-nuts/jsconsumer")
	}
	return c.Tracer
}

func (c Config) logger() *slog.Logger {
	if c.Logger == nil {
		return slog.Default()
	}
	return c.Logger
}

// isShutdownConsumeErr reports whether a consume error is the benign result
// of the connection going away during shutdown. [nuts.IsShutdownFetchErr]
// covers the core nats.go sentinels, but the jetstream consume loop surfaces
// its OWN [jetstream.ErrConnectionClosed] — a distinct value that wraps
// neither — so it must be matched separately or a clean rollout drain still
// logs a warning (the COR-923 noise this suppression exists to remove). As
// with the root classifier, it is only "clean" when ctx is already done; a
// mid-run connection loss is a genuine fault worth logging.
func isShutdownConsumeErr(ctx context.Context, err error) bool {
	return nuts.IsShutdownFetchErr(ctx, err) ||
		(ctx.Err() != nil && errors.Is(err, jetstream.ErrConnectionClosed))
}

// Runner is a live consume loop. Stop halts it and is idempotent.
type Runner struct {
	cc jetstream.ConsumeContext
	// closed is cc.Closed(), captured while the subscription is live (the
	// same channel is returned on every call, so capturing once avoids any
	// post-Stop race) — it closes when the consume loop has fully wound
	// down, including an in-flight handler.
	closed <-chan struct{}
	// watcherDone closes when Start's context-cancellation watcher exits. It is
	// intentionally internal: callers synchronize on Stop, while tests pin that
	// an explicit Stop does not retain a goroutine until the parent context ends.
	watcherDone <-chan struct{}
	stop        sync.Once
}

// Stop halts the consume loop and blocks until it has fully wound down —
// including an in-flight handler — so a caller may tear down what handlers
// use (stores, publishers, the NATS connection) the moment it returns: the
// cancel → join → drain shutdown ordering (COR-923). Safe on a nil or
// never-Started Runner, idempotent, and safe for concurrent use — an
// explicit Stop can race the context-cancel stop armed by Start. Must not be
// called from inside the handler; it would deadlock waiting on itself.
func (r *Runner) Stop() {
	if r == nil || r.cc == nil {
		return
	}
	r.stop.Do(r.cc.Stop)
	<-r.closed
}

// Start creates/updates the durable consumer on nc and begins delivering
// messages to onMsg, returning a Runner that Stops when ctx is cancelled. The
// stream must already exist (provisioned declaratively); callers whose cells
// opt in per-stream gate Start behind that opt-in so a cell without the stream
// doesn't error at CreateOrUpdateConsumer.
//
// Consume errors are logged at Warn, except a drain/close during shutdown —
// both the core nats.go sentinels ([nuts.IsShutdownFetchErr]) and jetstream's
// own connection-closed error — which is a clean exit rather than a fault.
func Start(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) (*Runner, error) {
	if err := cfg.validate(nc, onMsg); err != nil {
		return nil, err
	}
	js, err := jetstream.New(nc)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): jetstream.New: %w", cfg.Name, err)
	}
	cons, err := js.CreateOrUpdateConsumer(ctx, cfg.Stream, jetstream.ConsumerConfig{
		Durable:           cfg.Durable,
		AckPolicy:         jetstream.AckExplicitPolicy,
		AckWait:           cfg.EffectiveAckWait(),
		MaxDeliver:        cfg.EffectiveMaxDeliver(),
		FilterSubject:     cfg.FilterSubject,
		FilterSubjects:    cfg.FilterSubjects,
		InactiveThreshold: cfg.InactiveThreshold,
		MaxAckPending:     cfg.MaxAckPending,
	})
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): create consumer %s/%s: %w", cfg.Name, cfg.Stream, cfg.Durable, err)
	}
	consumeOpts := []jetstream.PullConsumeOpt{jetstream.ConsumeErrHandler(func(_ jetstream.ConsumeContext, cerr error) {
		if isShutdownConsumeErr(ctx, cerr) {
			return
		}
		cfg.logger().WarnContext(ctx, cfg.Name+": consume error", slog.Any("error", cerr))
	})}
	switch {
	case cfg.KeepInProgress:
		consumeOpts = append(consumeOpts, jetstream.PullMaxMessages(1))
	case cfg.MaxMessages > 0:
		consumeOpts = append(consumeOpts, jetstream.PullMaxMessages(cfg.MaxMessages))
	}
	cc, err := cons.Consume(onMsg, consumeOpts...)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): consume %s: %w", cfg.Name, cfg.Stream, err)
	}
	watcherDone := make(chan struct{})
	r := &Runner{cc: cc, closed: cc.Closed(), watcherDone: watcherDone}
	go func() {
		defer close(watcherDone)
		select {
		case <-ctx.Done():
			r.Stop()
		case <-r.closed:
		}
	}()
	return r, nil
}

// isRetryableStartError classifies the narrow set of failures that can become
// healthy without changing Config or replacing nc. Everything else returns to
// the owner so a bad deployment cannot stay alive indefinitely with no
// consumer. Unknown server-side 5xx responses are retried, except known
// permanent JetStream configuration/account errors whose API happens to use a
// 5xx status.
func isRetryableStartError(err error) bool {
	if errors.Is(err, jetstream.ErrStreamNotFound) ||
		errors.Is(err, nats.ErrNoResponders) ||
		errors.Is(err, nats.ErrTimeout) ||
		errors.Is(err, nats.ErrDisconnected) {
		return true
	}

	var jsErr jetstream.JetStreamError
	if !errors.As(err, &jsErr) || jsErr.APIError() == nil {
		return false
	}
	apiErr := jsErr.APIError()
	switch apiErr.ErrorCode { //nolint:exhaustive // unrecognized 5xx codes are deliberately retryable; all other unknown codes fail closed
	case jetstream.JSErrCodeBadRequest,
		jetstream.JSErrCodeConsumerCreate,
		jetstream.JSErrCodeConsumerNameExists,
		jetstream.JSErrCodeMaximumConsumersLimit,
		jetstream.JSErrCodeJetStreamNotEnabledForAccount,
		jetstream.JSErrCodeJetStreamNotEnabled,
		jetstream.JSErrCodeConsumerAlreadyExists,
		jetstream.JSErrCodeDuplicateFilterSubjects,
		jetstream.JSErrCodeOverlappingFilterSubjects,
		jetstream.JSErrCodeConsumerEmptyFilter,
		jetstream.JSErrCodeConsumerExists:
		return false
	default:
		return apiErr.Code >= 500
	}
}

// Retry envelope for [Run]'s supervision: exponential from runRetryInitial
// doubling to runRetryMax, reset once a consume loop survives longer than the
// max. Package vars (not consts) so tests can compress the schedule.
var (
	runRetryInitial = time.Second
	runRetryMax     = 30 * time.Second
)

// Run supervises the consume loop [Start] builds. Where Start is one-shot —
// an error at consumer creation is returned, and a consume loop that closes
// underneath the caller (consumer deleted on the server, subscription
// invalidated) stays closed — Run retries both with exponential backoff
// (runRetryInitial doubling to runRetryMax, reset after a loop that outlives
// the max). In particular a stream that is not provisioned yet at boot — the
// declarative-provisioning race — is a retry, not a crash.
//
// Run blocks until ctx is cancelled, then joins the live loop (including an
// in-flight handler, see [Runner.Stop]) before returning, so it composes with
// the cancel → join → drain shutdown ordering as the body of a supervised
// goroutine:
//
//	g.Go(func(ctx context.Context) {
//		if err := jsconsumer.Run(ctx, nc, cfg, onMsg); err != nil {
//			log.Error("consumer config rejected", "error", err)
//		}
//	})
//
// Local configuration errors and permanent server responses (invalid consumer
// configuration, authorization/account setup) can never succeed on retry and
// are returned immediately. A missing declarative stream, temporary transport
// failure, or unknown server-side 5xx response remains supervised. A nil return
// means a clean, ctx-driven exit.
func Run(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) error {
	if err := cfg.validate(nc, onMsg); err != nil {
		return err
	}
	delay := runRetryInitial
	for {
		// Each attempt gets a child context so the cancel-watcher goroutine
		// Start arms is released when the attempt dies, instead of one
		// accumulating per recreate for the life of the process.
		attemptCtx, cancelAttempt := context.WithCancel(ctx)
		r, err := Start(attemptCtx, nc, cfg, onMsg)
		if err != nil {
			cancelAttempt()
			if ctx.Err() != nil {
				return nil //nolint:nilerr // a Start error during shutdown is a clean, ctx-driven exit, not a fault to report
			}
			if !isRetryableStartError(err) {
				return err
			}
			cfg.logger().WarnContext(ctx, cfg.Name+": start consumer failed; retrying",
				slog.Any("error", err), slog.Duration("retry_in", delay))
		} else {
			started := time.Now()
			select {
			case <-ctx.Done():
				r.Stop()
				cancelAttempt()
				return nil
			case <-r.closed:
				cancelAttempt()
				if ctx.Err() != nil {
					return nil //nolint:nilerr // the loop closing during shutdown is the expected wind-down, not a fault
				}
				// A loop that ran long enough to be called healthy earns a
				// fresh envelope; a flapping one keeps escalating.
				if time.Since(started) >= runRetryMax {
					delay = runRetryInitial
				}
				cfg.logger().WarnContext(ctx, cfg.Name+": consume loop closed; recreating",
					slog.Duration("retry_in", delay))
			}
		}
		select {
		case <-ctx.Done():
			return nil
		case <-time.After(delay):
		}
		delay = min(delay*2, runRetryMax)
	}
}

// Process runs the per-message prologue shared by every consumer: open the
// consumer span (re-parented to the producer across the NATS hop), decode the
// payload, and on a decode error record it, log "<Name>: decode <Stream>;
// term", invoke onUndecodable (so the caller bumps its own drop metric with
// its own attributes), and Term the message — a poison payload won't decode on
// redelivery. On success it invokes handle with the span-enriched context, the
// live span (for RecordError/SetStatus on the business error paths), the
// message, and the decoded event; with Config.KeepInProgress set, an AckWait
// heartbeat runs for the duration of handle.
//
// Callers wire Process as the func they pass to Start AND the entry point
// their tests drive, so the decode-or-term path is exercised the same way in
// production and tests.
func Process[E any](
	ctx context.Context,
	msg jetstream.Msg,
	cfg Config,
	decode func([]byte) (E, error),
	handle func(ctx context.Context, span trace.Span, msg jetstream.Msg, ev E),
	onUndecodable func(ctx context.Context),
) {
	ctx, span := natsmsg.StartConsumerSpan(ctx, cfg.tracer(), msg, cfg.SpanName)
	defer span.End()

	ev, err := decode(msg.Data())
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		cfg.logger().WarnContext(ctx, cfg.Name+": decode "+cfg.Stream+"; term",
			slog.Any("error", err), slog.String("subject", msg.Subject()))
		if onUndecodable != nil {
			onUndecodable(ctx)
		}
		if termErr := msg.Term(); termErr != nil {
			cfg.logger().WarnContext(ctx, cfg.Name+": term failed", slog.Any("error", termErr))
		}
		return
	}
	if cfg.KeepInProgress {
		stop := natsmsg.KeepInProgress(msg.InProgress, cfg.EffectiveAckWait())
		defer stop()
	}
	handle(ctx, span, msg, ev)
}

// Package backoff is the redelivery policy for transiently-failed JetStream
// deliveries: a NakWithDelay envelope — flat by default, optionally growing
// multiplicatively per delivery — bounded by MaxDeliver, with an optional
// Term on the final delivery.
//
// The policy owns disposition and delay calculation only, and nothing wider:
// dead-letter capture, domain metrics/logging, and the decision of which
// failures are transient stay with the caller. It drives the modern
// [jetstream.Msg] API (NakOrTerm, NumDelivered, IsFinalDelivery).
//
// Delay calculation ([Policy.DelayFor]) is independent of message disposition:
// it is a pure function of the delivery count, so a caller can pin or meter the
// delay envelope without a message in hand.
//
// # Zero-value and unlimited semantics
//
// MaxDeliver matches [jetstream.ConsumerConfig.MaxDeliver]: a non-positive value
// (0 or [UnlimitedMaxDeliver]) means unlimited redeliveries, so no delivery is
// ever final and NakOrTerm always Naks. Note this reads zero differently from
// jsconsumer.Config.MaxDeliver, where 0 means "default to DefaultMaxDeliver":
// bridge with jsconsumer.Config.EffectiveMaxDeliver() (never the raw field), so
// an unset consumer MaxDeliver becomes the real default here instead of
// unlimited. Missing message metadata (a synthetic test message) reads as the
// first delivery — base NakDelay, never final — the safe default being another
// retry, not a Term.
//
// The Term-on-exhaustion posture is the COR-762 fix, lifted from
// mirror-pipeline's fanoutengine: on the final delivery a Nak is dropped
// silently by the broker (MaxDeliver reached), and on a WorkQueue stream the
// un-acked message then orphans — pinning the oldest-pending-age gauge — until
// StreamMaxAge finally expires it. Terming instead removes it cleanly. Streams
// where lingering is acceptable (a webhook stream whose max_age doubles as the
// retry backstop) leave TermOnExhaustion off and keep the plain Nak.
//
// Dead-letter capture stays with the caller, which should capture BEFORE
// disposing — gate it on [IsFinalDelivery]:
//
//	if backoff.IsFinalDelivery(msg, p.MaxDeliver) {
//		captureToDLQ(ctx, msg)
//	}
//	outcome, err := p.NakOrTerm(msg)
package backoff

import (
	"fmt"
	"math"
	"time"

	"github.com/nats-io/nats.go/jetstream"
)

// UnlimitedMaxDeliver is the explicit Policy.MaxDeliver value for unlimited
// redeliveries (matching jetstream.ConsumerConfig.MaxDeliver, where a
// non-positive value disables the delivery cap). The zero value means the same
// thing; the named constant lets a caller say so on purpose.
const UnlimitedMaxDeliver = -1

// Outcome is the disposition NakOrTerm chose, for the caller's metrics and
// logs.
type Outcome string

const (
	OutcomeNak  Outcome = "nak"
	OutcomeTerm Outcome = "term"
)

// Policy is the redelivery envelope a consumer applies to transient
// failures. MaxDeliver must match the consumer's on-server MaxDeliver — the
// policy detects the final delivery by comparing against it.
type Policy struct {
	// NakDelay is the base delay before redelivery, and with a zero Factor
	// the whole envelope: flat suits failures expected to clear on their own
	// timetable, with MaxDeliver bounding the total.
	NakDelay time.Duration
	// Factor is the optional multiplicative growth per prior delivery: the
	// Nth delivery naks with NakDelay × Factor^(N-1), capped at MaxDelay.
	// Values ≤ 1 (including the zero value) keep the flat envelope. Growing
	// envelopes suit failures that get cheaper to wait out than to retry —
	// a downstream in a crash loop, a rate limit — where hammering on the
	// flat cadence spends MaxDeliver too fast.
	Factor float64
	// MaxDelay caps the grown delay; it does nothing for a flat policy.
	// Zero with a growing Factor leaves growth bounded only by MaxDeliver
	// ending the redeliveries (the computed delay still saturates rather
	// than overflowing).
	MaxDelay time.Duration
	// MaxDeliver is the consumer's redelivery cap
	// (jetstream.ConsumerConfig.MaxDeliver). Non-positive (0 or
	// UnlimitedMaxDeliver) means unlimited redeliveries — matching the
	// jetstream field's semantics — so no delivery is ever final and NakOrTerm
	// always Naks.
	MaxDeliver int
	// TermOnExhaustion makes the final delivery Term instead of Nak, so a
	// work-queue message is removed cleanly rather than orphaning un-acked
	// (COR-762). Callers with a DLQ capture before calling NakOrTerm.
	TermOnExhaustion bool
}

// NakOrTerm applies the policy to a transiently-failed [jetstream.Msg]
// delivery: NakWithDelay (see [Policy.DelayFor]) for redelivery, or — on the
// final delivery with TermOnExhaustion set — Term. Without TermOnExhaustion the
// final delivery still Naks; the broker drops the Nak at MaxDeliver and the
// stream's retention decides the message's fate.
//
// The returned Outcome reports which disposition was chosen, for the caller's
// metrics and logs. A disposition error is worth a log line but nothing more:
// a failed Nak redelivers via AckWait expiry anyway, and a failed Term on a
// work-queue stream means the message lingers exactly as it would have without
// the policy.
func (p Policy) NakOrTerm(msg jetstream.Msg) (Outcome, error) {
	if p.TermOnExhaustion && IsFinalDelivery(msg, p.MaxDeliver) {
		if err := msg.Term(); err != nil {
			return OutcomeTerm, fmt.Errorf("term on final delivery: %w", err)
		}
		return OutcomeTerm, nil
	}
	if err := msg.NakWithDelay(p.DelayFor(NumDelivered(msg))); err != nil {
		return OutcomeNak, fmt.Errorf("nak with delay: %w", err)
	}
	return OutcomeNak, nil
}

// DelayFor reports the redelivery delay the policy applies after delivery
// number numDelivered (1 on first delivery): NakDelay for a flat policy,
// NakDelay × Factor^(numDelivered-1) capped at MaxDelay for a growing one.
// numDelivered ≤ 1 — including the 0 that [NumDelivered] reports when
// metadata is unavailable — reads as the first delivery. Exposed so a caller
// can log or meter the delay it is about to apply.
func (p Policy) DelayFor(numDelivered int) time.Duration {
	if p.Factor <= 1 || numDelivered <= 1 {
		return p.NakDelay
	}
	d := float64(p.NakDelay) * math.Pow(p.Factor, float64(numDelivered-1))
	if p.MaxDelay > 0 && d >= float64(p.MaxDelay) {
		return p.MaxDelay
	}
	if d >= float64(math.MaxInt64) {
		// Uncapped growth outran time.Duration; saturate instead of wrapping
		// negative (a negative NakWithDelay would redeliver immediately).
		return math.MaxInt64
	}
	return time.Duration(d)
}

// NumDelivered reports the JetStream delivery count of a [jetstream.Msg]
// (1 on first delivery), or 0 if metadata is unavailable (e.g. a synthetic test
// message).
func NumDelivered(msg jetstream.Msg) int {
	if meta, err := msg.Metadata(); err == nil && meta != nil {
		return int(meta.NumDelivered)
	}
	return 0
}

// IsFinalDelivery reports whether this is the last delivery before JetStream
// stops redelivering (NumDelivered has reached MaxDeliver), so a transient
// failure here is terminal rather than another Nak-and-retry. A non-positive
// maxDeliver means unlimited redeliveries (the jetstream.ConsumerConfig
// semantics), so no delivery is final — without the guard the zero value
// would read every delivery as final and Term on the first failure.
// Unavailable metadata also reads as non-final: the safe default is another
// retry, not a Term.
func IsFinalDelivery(msg jetstream.Msg, maxDeliver int) bool {
	if maxDeliver <= 0 {
		return false
	}
	if meta, err := msg.Metadata(); err == nil && meta != nil {
		return meta.NumDelivered >= uint64(maxDeliver)
	}
	return false
}

package natsmsg

import (
	"context"
	"fmt"
	"strconv"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
)

// dlqPublishTimeout bounds one dead-letter PublishMsg. The consume context has
// no deadline, and PublishMsg waits for the PubAck indefinitely; without a
// bound a NATS blip would hang the handler (and, since a one-in-flight consumer
// keeps a slot occupied, stall the consumer) instead of failing the capture
// loudly.
const dlqPublishTimeout = 15 * time.Second

// DLQ provenance headers added to the captured copy so a replay tool (or a
// human) can see why and from where a message was dead-lettered.
const (
	DLQReasonHeader    = "Nats-Dlq-Reason"
	DLQOriginHeader    = "Nats-Dlq-Origin-Subject"
	DLQDeliveredHeader = "Nats-Dlq-Delivered"
	DLQStreamSeqHeader = "Nats-Dlq-Stream-Seq"
)

// DLQPublisher is the publish surface DeadLetter needs — the modern
// [JetStream] publish primitive (satisfied by jetstream.JetStream), aliased
// so DeadLetter's signature reads in DLQ terms. Kept minimal so wiring can
// hand it the same JetStream handle the per-cell publishers already hold,
// and tests can stub it.
type DLQPublisher = JetStream

// SubjectToken sanitizes s into a single valid NATS subject token. NATS tokens
// cannot contain spaces, dots, or wildcards, so every character outside
// [a-z0-9_-] is replaced with '_' (and letters are lowercased). Use it to turn a
// human-readable dead-letter reason ("bad completion payload") into a subject
// token ("bad_completion_payload") — publishing to an unsanitized reason would
// fail, so the caller would never Ack the poison off a WorkQueue.
func SubjectToken(s string) string {
	// Iterate bytes, not runes: we only keep ASCII [a-z0-9_-] and map everything
	// else (including every byte of a multi-byte rune) to '_', so a byte loop is
	// both correct and free of a rune->byte narrowing conversion.
	b := make([]byte, 0, len(s))
	for i := range len(s) {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9', c == '_', c == '-':
			b = append(b, c)
		case c >= 'A' && c <= 'Z':
			b = append(b, c-'A'+'a')
		default:
			b = append(b, '_')
		}
	}
	if len(b) == 0 {
		return "unknown"
	}
	return string(b)
}

// DeadLetter republishes a poison message to dlqSubject, preserving its payload
// and headers and adding Nats-Dlq-* provenance (reason, origin subject,
// delivery count, stream sequence).
//
// It is the capture step a consumer runs before giving up on a message it can
// never process. DeadLetter copies the poison to a durable DLQ subject so it can
// be inspected or replayed, and the caller then removes the original from the
// stream — a Term on the final delivery (see backoff.Policy.TermOnExhaustion,
// whose doc notes callers "DLQ capture before calling NakOrTerm") or a plain
// Ack. Without this step a Term'd or MaxDeliver-exhausted message is discarded
// with no trail; DeadLetter is what makes the give-up auditable and recoverable.
//
// Returns an error if the republish fails; on error the caller MUST NOT remove
// the original — Nak or leave it so the poison is never dropped without a
// captured copy. Publishing is bounded by dlqPublishTimeout regardless of ctx's
// deadline.
func DeadLetter(ctx context.Context, pub DLQPublisher, dlqSubject string, msg jetstream.Msg, reason string) error {
	hdr := nats.Header{}
	for k, v := range msg.Headers() {
		hdr[k] = append([]string(nil), v...)
	}
	hdr.Set(DLQReasonHeader, reason)
	hdr.Set(DLQOriginHeader, msg.Subject())
	if meta, err := msg.Metadata(); err == nil && meta != nil {
		hdr.Set(DLQDeliveredHeader, strconv.FormatUint(meta.NumDelivered, 10))
		hdr.Set(DLQStreamSeqHeader, strconv.FormatUint(meta.Sequence.Stream, 10))
	}

	out := &nats.Msg{Subject: dlqSubject, Data: msg.Data(), Header: hdr}

	pubCtx, cancel := context.WithTimeout(ctx, dlqPublishTimeout)
	defer cancel()
	if _, err := pub.PublishMsg(pubCtx, out); err != nil {
		return fmt.Errorf("dead-letter publish to %q: %w", dlqSubject, err)
	}
	return nil
}

package nuts

import (
	"context"
	"log/slog"
	"slices"
	"sync"
	"testing"
	"time"

	natsserver "github.com/nats-io/nats-server/v2/server"
)

// runEmbeddedServer starts an in-process NATS server on a random loopback port
// and returns its client URL. The server is shut down when the test ends.
func runEmbeddedServer(t *testing.T) string {
	t.Helper()
	return runEmbeddedServerWith(t, &natsserver.Options{}).ClientURL()
}

// runEmbeddedServerWith starts an in-process NATS server from opts (host, port,
// and log/signal handling are forced to test-safe values) and returns the
// server handle for tests that drive server-side behavior such as lame duck
// mode. The server is shut down when the test ends.
func runEmbeddedServerWith(t *testing.T, opts *natsserver.Options) *natsserver.Server {
	t.Helper()
	opts.Host = "127.0.0.1"
	opts.Port = -1 // pick a free port
	opts.NoLog = true
	opts.NoSigs = true
	s, err := natsserver.NewServer(opts)
	if err != nil {
		t.Fatalf("new embedded nats server: %v", err)
	}
	go s.Start()
	if !s.ReadyForConnections(10 * time.Second) {
		t.Fatal("embedded nats server not ready in time")
	}
	t.Cleanup(s.Shutdown)
	return s
}

// capturingHandler is a thread-safe slog.Handler that records log messages so
// tests can assert what was logged, including from background goroutines.
type capturingHandler struct {
	mu   sync.Mutex
	msgs []string
}

func (h *capturingHandler) Enabled(context.Context, slog.Level) bool { return true }

func (h *capturingHandler) Handle(_ context.Context, r slog.Record) error {
	h.mu.Lock()
	h.msgs = append(h.msgs, r.Message)
	h.mu.Unlock()
	return nil
}

func (h *capturingHandler) WithAttrs([]slog.Attr) slog.Handler { return h }
func (h *capturingHandler) WithGroup(string) slog.Handler      { return h }

func (h *capturingHandler) has(msg string) bool {
	h.mu.Lock()
	defer h.mu.Unlock()
	return slices.Contains(h.msgs, msg)
}

func (h *capturingHandler) snapshot() []string {
	h.mu.Lock()
	defer h.mu.Unlock()
	return slices.Clone(h.msgs)
}

// waitFor blocks until a message equal to msg has been logged, or fails the
// test after a short deadline. Used to synchronize on logs emitted from a
// background loop goroutine.
func (h *capturingHandler) waitFor(t *testing.T, msg string) {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		if h.has(msg) {
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("did not observe log %q; saw %v", msg, h.snapshot())
}

// newCapturingLogger returns a logger writing to a fresh capturingHandler.
func newCapturingLogger() (*slog.Logger, *capturingHandler) {
	h := &capturingHandler{}
	return slog.New(h), h
}

package natsmsg

import (
	"context"
	"fmt"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"
)

// DefaultPublishTimeout bounds the wait for the broker's publish
// acknowledgment when a publisher's Timeout is zero. The bound matters because
// Entire connections reconnect forever and nats.go buffers publishes while
// disconnected: without it, a publisher holding an HTTP request or a message
// disposition would wait indefinitely behind an unreachable broker instead
// of failing over to its retry path (the caller's outbox, nak, or 5xx).
const DefaultPublishTimeout = 5 * time.Second

// StartProducerSpan opens a producer span named name on tr, pre-tagged with
// the standard messaging attributes (system=nats, operation.type=publish,
// destination=subject) — the publish-side counterpart of [StartConsumerSpan].
// Extra attrs are appended. The caller owns the span and must End it, and
// should Inject the returned ctx into the outgoing message so the consumer can
// re-parent.
func StartProducerSpan(ctx context.Context, tr trace.Tracer, subject, name string, attrs ...attribute.KeyValue) (context.Context, trace.Span) {
	base := append([]attribute.KeyValue{
		attribute.String("messaging.system", "nats"),
		attribute.String("messaging.operation.type", "publish"),
		attribute.String("messaging.destination.name", subject),
	}, attrs...)
	return tr.Start(ctx, name, trace.WithSpanKind(trace.SpanKindProducer), trace.WithAttributes(base...)) //nolint:spancheck // the caller owns the span and Ends it
}

// JetStream is the slice of the modern [jetstream.JetStream] API the
// [Publisher] drives — the ctx-native PublishMsg. jetstream.JetStream
// satisfies it; a test stubs the one method instead of faking the full
// interface. [DLQPublisher] is an alias of it: dead-lettering and publishing
// share the identical publish surface, so a caller can hand both the one
// JetStream handle it already holds.
type JetStream interface {
	PublishMsg(ctx context.Context, msg *nats.Msg, opts ...jetstream.PublishOpt) (*jetstream.PubAck, error)
}

// Publisher is the JetStream publish core shared by Entire's producers: a
// producer span, W3C trace-context injection, Nats-Msg-Id dedup, and a
// bounded wait for the broker's ack. Every service had grown its own copy of
// exactly this prologue around PublishMsg; Publisher owns the prologue and
// nothing else — subject construction, payload encoding, domain
// metrics/logging, and the response to a failed publish (outbox retry, nak,
// HTTP 5xx) stay with the caller.
type Publisher struct {
	// JS is the JetStream publish surface (satisfied by jetstream.JetStream).
	JS JetStream
	// Tracer opens the producer span; nil uses the global OTel tracer
	// provider.
	Tracer trace.Tracer
	// Timeout bounds the wait for the broker's PubAck; 0 uses
	// DefaultPublishTimeout. It derives from the caller's ctx, so an
	// already-cancelled ctx still fails fast.
	Timeout time.Duration
	// Operation is the caller-selected producer span name (e.g.
	// "repo.ops.publish"); empty falls back to "publish <subject>". It names the
	// span only — the messaging operation is recorded as the standard
	// messaging.operation.type=publish attribute, per OTel semantic conventions,
	// which reserve messaging.operation.name for the system-specific operation
	// (send/ack/nack), not an application span name.
	Operation string
}

// Publish sends msg and waits — bounded by Timeout — for the broker's ack,
// wrapped in a producer span named by Operation (or "publish <subject>" when
// unset). A non-empty msgID is set as the Nats-Msg-Id header, the broker-side
// dedup key within the stream's duplicate window; empty leaves any Nats-Msg-Id
// already on msg untouched. Trace context from ctx is injected into msg's
// headers (msg is mutated) so the consumer span re-parents across the hop.
//
// attrs are the caller's domain span attributes (placement, job identity, …) —
// appended to the standard messaging.* set on the producer span. They stay
// caller-owned: the shared package does not know them, but records them on the
// span it owns so a migrated caller keeps its existing producer-span tags.
//
// The returned PubAck reports where the message landed and whether the
// broker deduplicated it (PubAck.Duplicate) — a duplicate is a normal
// outcome for an at-least-once producer retrying, not an error. The
// stream, sequence, and duplicate outcome are also recorded on the span.
func (p Publisher) Publish(ctx context.Context, msg *nats.Msg, msgID string, attrs ...attribute.KeyValue) (*jetstream.PubAck, error) {
	tr := p.Tracer
	if tr == nil {
		tr = otel.Tracer("github.com/entireio/go-nuts/natsmsg")
	}
	name := p.Operation
	if name == "" {
		name = "publish " + msg.Subject
	}
	ctx, span := StartProducerSpan(ctx, tr, msg.Subject, name, attrs...)
	defer span.End()

	if msgID != "" {
		if msg.Header == nil {
			msg.Header = nats.Header{}
		}
		msg.Header.Set(nats.MsgIdHdr, msgID)
		span.SetAttributes(attribute.String("messaging.message.id", msgID))
	}
	Inject(ctx, msg)

	timeout := p.Timeout
	if timeout == 0 {
		timeout = DefaultPublishTimeout
	}
	pubCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	ack, err := p.JS.PublishMsg(pubCtx, msg)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "publish")
		return nil, fmt.Errorf("natsmsg: publish %s: %w", msg.Subject, err)
	}
	span.SetAttributes(
		attribute.String("messaging.nats.stream", ack.Stream),
		attribute.Int64("messaging.nats.sequence", ClampToInt64(ack.Sequence)),
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)
	return ack, nil
}

