20	// fakeDLQ records dead-letter captures, or fails them on demand so the
21	// never-drop path can be exercised.
22	type fakeDLQ struct {
23		mu   sync.Mutex
24		msgs []*nats.Msg
25		err  error
26	}
27	
28	func (f *fakeDLQ) PublishMsg(_ context.Context, m *nats.Msg, _ ...jetstream.PublishOpt) (*jetstream.PubAck, error) {
29		f.mu.Lock()
30		defer f.mu.Unlock()
31		if f.err != nil {
32			return nil, f.err
33		}
34		f.msgs = append(f.msgs, m)
35		return &jetstream.PubAck{Stream: "repo_refs_dlq_v1", Sequence: uint64(len(f.msgs))}, nil
36	}
37	
38	func (f *fakeDLQ) captured() []*nats.Msg {
39		f.mu.Lock()
40		defer f.mu.Unlock()
41		return append([]*nats.Msg(nil), f.msgs...)
42	}
43	
44	var _ natsmsg.DLQPublisher = (*fakeDLQ)(nil)
