46	// testRetryConfig is the shape of the first adopter's config
47	// (search-indexer-refs): a flat 5-minute rung well under the 15-minute
48	// breaker threshold, MaxDeliver 5, capture to the ref-event DLQ.
49	func testRetryConfig(pub natsmsg.DLQPublisher) RetryConfig {
50		return RetryConfig{
51			Backoff:    backoff.Policy{NakDelay: 5 * time.Minute, MaxDeliver: 5},
52			DLQSubject: "repo.refs.dlq",
53			Publisher:  pub,
54			Name:       "search-indexer-refs",
55		}
56	}
