58	func newTestRetry(t *testing.T, mutate func(*RetryConfig)) (*Retry, *fakeDLQ) {
59		t.Helper()
60		pub := &fakeDLQ{}
61		cfg := testRetryConfig(pub)
62		if mutate != nil {
63			mutate(&cfg)
64		}
65		r, err := NewRetry(cfg)
66		if err != nil {
