72	// armFloor pins the Retry's observed ack floor at seq and freezes its clock
73	// so the floor reads as stationary for age — the state the poll loop would
74	// have built up over a real stall.
75	func armFloor(r *Retry, seq uint64, age time.Duration) {
76		now := time.Now()
77		r.clock = func() time.Time { return now }
78		r.observeFloor(seq, now.Add(-age))
79	}
