100			name string
101			cfg  RetryConfig
102			want string
103		}{
104			{"no publisher", func() RetryConfig { c := testRetryConfig(pub); c.Publisher = nil; return c }(), "Publisher"},
105			{"no dlq subject", func() RetryConfig { c := testRetryConfig(pub); c.DLQSubject = ""; return c }(), "DLQSubject"},
106			{"unlimited max deliver", func() RetryConfig {
107				c := testRetryConfig(pub)
108				c.Backoff.MaxDeliver = backoff.UnlimitedMaxDeliver
109				return c
110			}(), "MaxDeliver"},
111			{"term on exhaustion", func() RetryConfig {
112				c := testRetryConfig(pub)
113				c.Backoff.TermOnExhaustion = true
114				return c
115			}(), "TermOnExhaustion"},
116			{"zero nak delay", func() RetryConfig { c := testRetryConfig(pub); c.Backoff.NakDelay = 0; return c }(), "NakDelay"},
117			{"uncapped growth", func() RetryConfig {
118				c := testRetryConfig(pub)
119				c.Backoff.Factor = 2
120				return c
121			}(), "MaxDelay"},
122			{"rung longer than the breaker window", func() RetryConfig {
123				c := testRetryConfig(pub)
124				c.Backoff.NakDelay = 30 * time.Minute
125				return c
126			}(), "exceeds FloorAge"},
127			{"grown rung longer than the breaker window", func() RetryConfig {
128				c := testRetryConfig(pub)
129				c.Backoff.NakDelay = time.Minute
130				c.Backoff.Factor = 4
131				c.Backoff.MaxDelay = time.Hour
132				return c
133			}(), "exceeds FloorAge"},
134			{"poll slower than the breaker window", func() RetryConfig {
135				c := testRetryConfig(pub)
136				c.FloorPoll = 20 * time.Minute
137				return c
138			}(), "FloorPoll"},
139			{"negative poll", func() RetryConfig { c := testRetryConfig(pub); c.FloorPoll = -time.Second; return c }(), "FloorPoll"},
140			{"negative min deliveries", func() RetryConfig {
141				c := testRetryConfig(pub)
142				c.MinDeliveries = -1
143				return c
144			}(), "MinDeliveries"},
145			{"min deliveries past the cap", func() RetryConfig {
146				c := testRetryConfig(pub)
147				c.MinDeliveries = 9
148				return c
149			}(), "MinDeliveries"},
150		}
151		for _, tt := range tests {
