// TestProbeBlockerAfterDrain: the steady-state case. The consumer fully
// drains, THEN a poison message arrives with non-matching messages before it.
// The server sets asflr from the drain high-water mark, not from a pending
// scan, so the gap may land between the floor and the blocker.
func TestProbeBlockerAfterDrain(t *testing.T) {
	_, js := runTestEnv(t)
	if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
		Name: "probe2_v1", Subjects: []string{"p2.>"},
	}); err != nil {
		t.Fatalf("create stream: %v", err)
	}
	cons, err := js.CreateOrUpdateConsumer(t.Context(), "probe2_v1", jetstream.ConsumerConfig{
		Durable: "probe2", AckPolicy: jetstream.AckExplicitPolicy,
		AckWait: time.Second, MaxDeliver: 100, FilterSubject: "p2.keep",
	})
	if err != nil {
		t.Fatalf("create consumer: %v", err)
	}

	var mu sync.Mutex
	var poisonStream, poisonConsumer, poisonDeliv uint64
	drained := make(chan struct{}, 8)
	cc, err := cons.Consume(func(m jetstream.Msg) {
		meta, merr := m.Metadata()
		if merr != nil {
			return
		}
		if string(m.Data()) == "poison" {
			mu.Lock()
			poisonStream, poisonConsumer, poisonDeliv = meta.Sequence.Stream, meta.Sequence.Consumer, meta.NumDelivered
			mu.Unlock()
			_ = m.NakWithDelay(200 * time.Millisecond)
			return
		}
		_ = m.Ack()
		drained <- struct{}{}
	})
	if err != nil {
		t.Fatalf("consume: %v", err)
	}
	defer cc.Stop()

	// Phase 1: publish 2 matching messages and let the consumer fully drain.
	for range 2 {
		if _, err := js.Publish(t.Context(), "p2.keep", []byte("ok")); err != nil {
			t.Fatalf("publish: %v", err)
		}
	}
	for range 2 {
		select {
		case <-drained:
		case <-time.After(5 * time.Second):
			t.Fatal("did not drain")
		}
	}
	i1, _ := cons.Info(t.Context())
	t.Logf("after drain: AckFloor.Stream=%d AckFloor.Consumer=%d Delivered.Stream=%d",
		i1.AckFloor.Stream, i1.AckFloor.Consumer, i1.Delivered.Stream)

	// Phase 2: 3 non-matching messages, then the poison one.
	for range 3 {
		if _, err := js.Publish(t.Context(), "p2.skip", []byte("skip")); err != nil {
			t.Fatalf("publish: %v", err)
		}
	}
	if _, err := js.Publish(t.Context(), "p2.keep", []byte("poison")); err != nil {
		t.Fatalf("publish: %v", err)
	}

	deadline := time.Now().Add(6 * time.Second)
	for time.Now().Before(deadline) {
		mu.Lock()
		n := poisonDeliv
		mu.Unlock()
		if n >= 3 {
			break
		}
		time.Sleep(50 * time.Millisecond)
	}
	i2, _ := cons.Info(t.Context())
	mu.Lock()
	defer mu.Unlock()
	t.Logf("stalled: AckFloor.Stream=%d AckFloor.Consumer=%d | poison stream=%d consumer=%d deliv=%d",
		i2.AckFloor.Stream, i2.AckFloor.Consumer, poisonStream, poisonConsumer, poisonDeliv)
