	quarantine, floor, age := r.shouldQuarantine(msg, delivered)

	s := Settlement{
		Delivered:      delivered,
		Floor:          floor,
		FloorAge:       age,
		FailingFor:     r.failingFor(delivered),
		BreakerTripped: quarantine,
	}
