package jsconsumer

import (
	"sync"
	"testing"
	"time"

	"github.com/nats-io/nats.go/jetstream"
)

// TestProbeNakVsBackOff — throwaway. Does a consumer's BackOff ladder govern
// redelivery after a plain Nak(), or only after an AckWait timeout?
func TestProbeNakVsBackOff(t *testing.T) {
	_, js := runTestEnv(t)
	if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
		Name: "nak_v1", Subjects: []string{"nak.>"},
	}); err != nil {
		t.Fatalf("create stream: %v", err)
	}

	ladder := []time.Duration{3 * time.Second, 3 * time.Second, 3 * time.Second, 3 * time.Second}

	run := func(name, subject, durable string, disposition func(jetstream.Msg)) []time.Duration {
		if _, err := js.Publish(t.Context(), subject, []byte("x")); err != nil {
			t.Fatalf("publish: %v", err)
		}
		cons, err := js.CreateOrUpdateConsumer(t.Context(), "nak_v1", jetstream.ConsumerConfig{
			Durable:       durable,
			AckPolicy:     jetstream.AckExplicitPolicy,
			AckWait:       ladder[0],
			BackOff:       ladder,
			MaxDeliver:    5,
			FilterSubject: subject,
		})
		if err != nil {
			t.Fatalf("create consumer: %v", err)
		}
		var mu sync.Mutex
		var at []time.Time
		cc, err := cons.Consume(func(m jetstream.Msg) {
			mu.Lock()
			at = append(at, time.Now())
			n := len(at)
			mu.Unlock()
			if n < 4 {
				disposition(m)
			}
		})
		if err != nil {
			t.Fatalf("consume: %v", err)
		}
		defer cc.Stop()

		deadline := time.Now().Add(20 * time.Second)
		for time.Now().Before(deadline) {
			mu.Lock()
			n := len(at)
			mu.Unlock()
			if n >= 4 {
				break
			}
			time.Sleep(20 * time.Millisecond)
		}
		mu.Lock()
		defer mu.Unlock()
		var gaps []time.Duration
		for i := 1; i < len(at); i++ {
			gaps = append(gaps, at[i].Sub(at[i-1]).Round(50*time.Millisecond))
		}
		t.Logf("%-22s deliveries=%d gaps=%v", name, len(at), gaps)
		return gaps
	}

	nakGaps := run("plain Nak()", "nak.plain", "plain", func(m jetstream.Msg) { _ = m.Nak() })
	run("NakWithDelay(3s)", "nak.delayed", "delayed", func(m jetstream.Msg) {
		_ = m.NakWithDelay(3 * time.Second)
	})
	run("no ack (AckWait)", "nak.timeout", "timeout", func(jetstream.Msg) {})

	t.Logf("VERDICT: if plain-Nak gaps are ~0s the server ladder does NOT govern Nak; got %v", nakGaps)
	t.Fatal("probe")
}

